                  stackId="1"
                  name="Rocket Lab"
                  fill={COLORS.rocketLab}
                  stroke={COLORS.rocketLab}
                />
                <Area
                  type="monotone"
                  dataKey="rest"
                  stackId="1"
                  name="Rest of world"
                  fill={COLORS.rest}
                  stroke={COLORS.rest}
                />
              </ComposedChart>
            </ResponsiveContainer>
          </div>
        ) : null}

        {panel === "us-mix" ? (
