                    nameKey="operator"
                    cx="50%"
                    cy="50%"
                    outerRadius={110}
                    label={({ operator, usSharePct }) =>
                      `${operator.split(" ")[0]} ${usSharePct}%`
                    }
                  >
                    {US_OPERATOR_MIX_2025.map((row, i) => (
                      <Cell
                        key={row.operator}
                        fill={
                          [
